mapper.select:
SELECT T1.FINPROD_ID, T1.FINPROD_TYPE2, T1.FINPROD_NAME, T1.FINPROD_MARKET_ID, T1.VDATE, T1.MDATE, T1.ISSUE_AMT, T2.TYPE_6, T4.PAY_CYCLE, T5.BASIS, T4.PAY_TDAY_RULE， T3.CASH_ID FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_INFO T3 ON T3.FINPROD_ID = T1.FINPROD_ID
AND T3.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
AND T3.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND T3.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
LEFT JOIN FIN_CASH_PAY_RULE T4 ON T4.CASH_ID = T3.CASH_ID AND T4.EFF_DATE = T1.VDATE LEFT JOIN FIN_CASH_CALC_RULE T5 ON T5.CASH_ID = T3.CASH_ID AND T5.EFF_DATE = T1.VDATE
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
